insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-08','en-b1-08',null,3,8,'published',1,'{"id":"en-b1-08","baseId":"en-b1-08","revision":1,"level":"B1","levelIndex":3,"order":8,"title":"Reported speech va savollarni yetkazish","objective":"Boshqaning xabari va savolini bevosita iqtibossiz aytasiz.","context":"To‘garak rahbarining xabari kelmagan do‘stga yetkaziladi.","prerequisites":["en-b1-07"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas.","Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas.","Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang."],"pattern":"said that … / told me … / asked where I lived / asked if I was ready","examples":["She said she was ready.","He told me the room was closed.","Lola asked where I lived.","The teacher asked if we were ready.","Ali said he would call later.","She told us to bring notebooks."],"vocabulary":[{"id":"en-b1-08-v0","term":"report","meaning":"yetkazmoq","ipa":"/rɪˈpɔːt/","collocation":"report a message","example":"Reporting a message is useful only if the new listener can understand what to do."},{"id":"en-b1-08-v1","term":"later","meaning":"keyinroq","ipa":"/ˈleɪtə/","collocation":"call later","example":"Ali said he would call later."},{"id":"en-b1-08-v2","term":"whether","meaning":"… yoki yo‘qmi","ipa":"/ˈweðə/","collocation":"ask whether","example":"Ali asked where the library entrance was and whether the meeting started at four."},{"id":"en-b1-08-v3","term":"remind","meaning":"eslatmoq","ipa":"/rɪˈmaɪnd/","collocation":"remind a friend","example":"remind a friend"}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["said that … / told me … / asked where I lived / asked if I was ready","She said she was ready.","He told me the room was closed."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["To‘garak rahbarining xabari kelmagan do‘stga yetkaziladi.","Lola asked where I lived.","Ali said he would call later."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The teacher asked if we were ready.","audio":"/english-course/v7.23/en-b1-08-dictation.mp3"},"exercises":[{"id":"en-b1-08-choice","type":"choice","skill":"grammar","prompt":"Reported questionni tanlang.","answers":["He asked if I was ready."],"explanation":"Gap tartibi I was.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["He asked if I was ready.","He asked was I ready?","He asked if was I ready."]},{"id":"en-b1-08-gap","type":"grammarFill","skill":"grammar","prompt":"She ___ me she was ready. (tell, past)","answers":["told"],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She said she was ready."],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","tokens":["She","said","she","was","ready."]},{"id":"en-b1-08-fix","type":"correction","skill":"grammar","prompt":"She asked where did I live.","answers":["She asked where I lived."],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yetkazmoq","keyinroq","… yoki yo‘qmi","eslatmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","left":["report","later","whether","remind"],"options":["yetkazmoq","keyinroq","… yoki yo‘qmi","eslatmoq"]},{"id":"en-b1-08-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["She said she was ready."],"tokens":["She","said","she","was","ready."],"hint":"said that … / told me … / asked where I lived / asked if I was ready","explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas."},{"id":"en-b1-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Kelajak uchrashuvlari va taxminlar: Jadvalni tanlang.","answers":["The train leaves at eight."],"explanation":"Train leaves — jadval.","hint":"train leaves / we’re meeting / going to prepare / will help / when I arrive","options":["The train leaves at eight.","I’ll carry your bag.","I think it will be useful."],"recap":true,"sourceLesson":"Kelajak uchrashuvlari va taxminlar"},{"id":"en-b1-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · First va Second Conditional: real va xayoliy: Real ehtimol qaysi?","answers":["If we get funding, we will start."],"explanation":"Present + will real kelajak sharti.","hint":"If + present, will … / If + past, would …","options":["If we get funding, we will start.","If we had funding, we would start.","We started last year."],"recap":true,"sourceLesson":"First va Second Conditional: real va xayoliy"},{"id":"en-b1-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Passive: ish va natijaga e’tibor: Passive tuzilmasini tanlang.","answers":["Books are collected."],"explanation":"Be + V3.","hint":"are collected / was cleaned; by + agent when relevant","options":["Books are collected.","Books collected are students.","Books are collect."],"recap":true,"sourceLesson":"Passive: ish va natijaga e’tibor"}],"reading":{"title":"Reported speech va savollarni yetkazish — vaziyat","text":"Ali missed the club meeting, so Lola sent him a summary. The teacher had said that Room 3 was closed and that the next meeting would be in the library. She had asked everyone to bring a notebook. Lola told Ali that they were preparing short talks about local places. Ali asked where the library entrance was and whether the meeting started at four. Lola explained that the entrance was near the park and that the meeting started at half past four. She did not repeat every sentence exactly, but she kept the important details. Before sending the message, she checked the time again. Ali thanked her and said he would prepare a photo for his talk. Reporting a message is useful only if the new listener can understand what to do.","sentences":["Ali missed the club meeting, so Lola sent him a summary.","The teacher had said that Room 3 was closed and that the next meeting would be in the library.","She had asked everyone to bring a notebook.","Lola told Ali that they were preparing short talks about local places.","Ali asked where the library entrance was and whether the meeting started at four.","Lola explained that the entrance was near the park and that the meeting started at half past four.","She did not repeat every sentence exactly, but she kept the important details.","Before sending the message, she checked the time again.","Ali thanked her and said he would prepare a photo for his talk.","Reporting a message is useful only if the new listener can understand what to do."],"questions":[{"id":"en-b1-08-reading0","type":"choice","skill":"reading","prompt":"Uchrashuv nechada boshlanadi?","answers":["half past four"],"explanation":"Lola 4:30 deb aniqlashtiradi.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["half past four","four","five"]},{"id":"en-b1-08-reading1","type":"choice","skill":"reading","prompt":"Nega hamma gap so‘zma-so‘z berilmagan?","answers":["a summary keeps important details"],"explanation":"Vazifa amaliy mazmunni yetkazish.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["a summary keeps important details","she forgot the entire message","reported speech forbids facts"]},{"id":"en-b1-08-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["Ali missed the club meeting, so Lola sent him a summary.","The teacher had said that Room 3 was closed and that the next meeting would be in the library.","She had asked everyone to bring a notebook.","Lola told Ali that they were preparing short talks about local places.","Ali asked where the library entrance was and whether the meeting started at four.","Lola explained that the entrance was near the park and that the meeting started at half past four.","She did not repeat every sentence exactly, but she kept the important details.","Before sending the message, she checked the time again.","Ali thanked her and said he would prepare a photo for his talk.","Reporting a message is useful only if the new listener can understand what to do."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"The teacher said the next meeting would be in the library. She told us to bring notebooks. Ali asked whether it started at four. Lola explained that it started at half past four, near the park entrance.","audio":"/english-course/v7.23/en-b1-08.mp3","synthetic":true,"questions":[{"id":"en-b1-08-listening0","type":"choice","skill":"listening","prompt":"Nima olib kelish aytilgan?","answers":["notebooks"],"explanation":"Told us to bring notebooks.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["notebooks","food","tickets"]},{"id":"en-b1-08-listening1","type":"choice","skill":"listening","prompt":"Soat qaysi?","answers":["4:30"],"explanation":"Half past four.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["4:30","4:00","5:30"]},{"id":"en-b1-08-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["library","4:30"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","rows":["Joy","Vaqt"]},{"id":"en-b1-08-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The teacher asked if we were ready."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"said that … / told me … / asked where I lived / asked if I was ready","audio":"/english-course/v7.23/en-b1-08-dictation.mp3","transcript":"The teacher asked if we were ready."}]},"writing":{"task":"Ustozning xabarini kelmagan do‘stingizga muhim ma’lumotlarni saqlab yetkazing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Hi Ali, our teacher said that the next meeting would be in the library because Room 3 was closed. She told us to bring notebooks and asked us to prepare a short talk about a local place. You asked whether the meeting started at four. I checked again, and it starts at half past four. The entrance is near the park. The teacher also reminded us to choose one clear photo rather than many unrelated pictures. Please tell me if you need help finding the entrance. I can meet you outside ten minutes before the talk begins.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["She said she was ready.","He told me the room was closed.","Lola asked where I lived."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Qisqa xabarni tinglang va boshqa sherigingizga o‘z so‘zingiz bilan yetkazing.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ustozning xabarini kelmagan do‘stingizga muhim ma’lumotlarni saqlab yetkazing.","exit":[[{"id":"en-b1-08-exit0","type":"grammarFill","skill":"grammar","prompt":"He ___ me the room was closed.","answers":["told"],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-exit1","type":"grammarFill","skill":"grammar","prompt":"She asked ___ we were ready.","answers":["if"],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-exit2","type":"grammarFill","skill":"grammar","prompt":"Ali said he ___ call later.","answers":["would"],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-exit3","type":"choice","skill":"grammar","prompt":"Say bilan qaysi gap to‘g‘ri?","answers":["She said she was ready."],"explanation":"Say + xabar.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["She said she was ready.","She said me ready.","She said to ready me."]},{"id":"en-b1-08-exit4","type":"choice","skill":"grammar","prompt":"Reported savolda tartib qanday?","answers":["statement order"],"explanation":"Where I lived.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["statement order","inversion always","do/does always"]}],[{"id":"en-b1-08-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He told me the room was closed."],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","tokens":["He","told","me","the","room","was","closed."]},{"id":"en-b1-08-exit-b1","type":"grammarFill","skill":"grammar","prompt":"She asked ___ we were ready.","answers":["if"],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready"},{"id":"en-b1-08-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The teacher asked if we were ready."],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","tokens":["The","teacher","asked","if","we","were","ready."]},{"id":"en-b1-08-exit-b3","type":"choice","skill":"grammar","prompt":"Say bilan qaysi gap to‘g‘ri?","answers":["She said she was ready."],"explanation":"Say + xabar.","hint":"said that … / told me … / asked where I lived / asked if I was ready","options":["She said she was ready.","She said me ready.","She said to ready me."]},{"id":"en-b1-08-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She told us to bring notebooks."],"explanation":"O‘tgan reporting fe’ldan keyin shakl ko‘pincha orqaga siljiydi: She said, “I am ready” → She said she was ready. Mazmun hali haqiqiy bo‘lsa har doim backshift shart emas. Say xabarni, tell odatda kimga aytilganini oladi: told me. Said me standart shakl emas. Reported questionda savol tartibi emas, gap tartibi: She asked where I lived. Yes/no savolda if/whether. Olmosh, vaqt va joyni haqiqiy vaziyatga moslang.","hint":"said that … / told me … / asked where I lived / asked if I was ready","tokens":["She","told","us","to","bring","notebooks."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars ma